"""Extract actual mouse callback/default destination and the engine table initializer."""
import hashlib
import json
from pathlib import Path
import re
import runpy
import sys

root = Path(sys.argv[1]).resolve()
out = Path(sys.argv[2]).resolve()
out.mkdir(parents=True, exist_ok=True)
sys.path.insert(0, str(root / 'tools'))
from client_module_layouts import clean, fields

# Reuse the real engine model view generated by the existing client ABI fixture.
runpy.run_path(str(root / 'tests/native/client_abi/prepare_fixtures.py'), run_name='client_abi_types')
receipts = []


def extract(path, pattern):
    text = path.read_bytes().decode('latin1')
    match = re.search(pattern, text)
    if not match:
        raise ValueError('Required owned callback is missing: ' + pattern)
    end = text.index('{', match.start()) + 1
    depth = 1
    while depth:
        depth += (text[end] == '{') - (text[end] == '}')
        end += 1
    code = text[match.start():end]
    receipts.append({'path': str(path), 'source_sha256': hashlib.sha256(path.read_bytes()).hexdigest(),
                     'body_sha256': hashlib.sha256(code.encode('latin1')).hexdigest()})
    return code


callback = extract(root / 'src/engine/cdll_int.cpp', r'int hudGetClientMousePositionAndCenter\(')
destination = extract(root / 'src/engine/module.cpp', r'void NullClientMousePositionAndCenterDst\(')
table = extract(root / 'src/engine/cdll_int.cpp', r'cl_enginefunc_t cl_enginefuncs\s*=') + ';'
api = (root / 'src/engine/APIProxy.h').read_bytes().decode('latin1')
members = fields(api, 'cl_enginefunc_t')
values = table[table.index('{') + 1:table.rindex('}')].split(',')
if len(members) != len(values):
    raise ValueError('Incomplete engine initializer')
stubs = []
for index, (member, value) in enumerate(zip(members, values)):
    value = re.sub(r'\([^)]*\)', '', value).strip()
    if value == 'hudGetClientMousePositionAndCenter':
        continue
    name = value.lstrip('&')
    if not re.fullmatch(r'\w+', name):
        raise ValueError('Unknown engine initializer value: ' + value)
    actual = 'decltype(cl_enginefunc_t::' + member + ')'
    if value.startswith('&'):
        stubs.append('std::remove_pointer<' + actual + '>::type ' + name + '{};')
    else:
        stubs.append('constexpr auto ' + name + ' = &UnrelatedCallback<' + actual + ', '
                     + str(index) + '>::Call;')
(out / 'actual_callback.inc').write_text(callback + '\n')
(out / 'actual_destination.inc').write_text(destination + '\n')
(out / 'actual_engine_table.inc').write_text('namespace controlled_engine {\n' + '\n'.join(stubs)
    + '\n' + table + '\n}\nusing controlled_engine::cl_enginefuncs;\n')
(out / 'extracted.json').write_text(json.dumps(receipts, indent=2) + '\n')
